struct Result { int label=-1; float nearest=0,alternative=0; };
inline Result predict(const demo_features::Pattern& input,float durationMs){
 float distances[]={1e30f,1e30f};
 for(unsigned i=0;i<COUNT;++i)distances[CLASS[i]]=std::min(distances[CLASS[i]],demo_features::distance(input,TEMPLATES[i]));
 unsigned best=distances[0]<=distances[1]?0:1,other=1-best;
 Result r;r.nearest=distances[best];r.alternative=distances[other];
 if(distances[best]<=LIMITS[best] && distances[best]<=.80f*distances[other] && durationMs>=MIN_MS[best] && durationMs<=MAX_MS[best])r.label=int(best);
 return r;
}
